<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\RelyingParty\Infrastructure\Driven;

use Psr\EventDispatcher\EventDispatcherInterface;
use Closure;
use Override;
use Throwable;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\Gateway\RelyingPartyWriteGateway;
use Civi\Lughauth\Features\Access\RelyingParty\Infrastructure\Connector\Pdo\RelyingPartyPdoConnector;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\Gateway\RelyingPartySlide;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\Gateway\RelyingPartyCursor;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\Gateway\RelyingPartyFilter;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\RelyingPartyRef;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\RelyingParty;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\EntityChangelog\EntityChangelogService;

class RelyingPartyWriteRepositoryAdapter implements RelyingPartyWriteGateway
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly RelyingPartyPdoConnector $conn,
        private readonly EventDispatcherInterface $dispatcher,
        private readonly EntityChangelogService $changelog,
    ) {
    }
    #[Override]
    public function resolveForUpdate(RelyingPartyRef $ref): ?RelyingParty
    {
        return $this->conn->retrieveForUpdate(new RelyingPartyFilter(uids: [ $ref->uid() ]));
    }
    #[Override]
    public function listForUpdate(?RelyingPartyFilter $filter = null, ?RelyingPartyCursor $cursor = null): RelyingPartySlide
    {
        $this->logDebug("List for update of Relying party on adapter ");
        $span = $this->startSpan("List for update of Relying party on adapter");
        try {
            $values = $this->conn->listForUpdate($filter, $cursor);
            $last = end($values);
            return new RelyingPartySlide(function (RelyingPartySlide $slide, ?RelyingPartyCursor$next) use ($filter) {
                return $this->listForUpdate($filter, $next);
            }, new RelyingPartyCursor($cursor?->limit() ?? 100, $last->uid ?? null), $values);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function retrieveForUpdate(RelyingPartyFilter $filter): ?RelyingParty
    {
        $this->logDebug("Retrieve for update of Relying party on adapter ");
        $span = $this->startSpan("Retrieve for update of Relying party on adapter");
        try {
            return $this->conn->retrieveForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function existsForUpdate(?RelyingPartyFilter $filter): bool
    {
        $this->logDebug("Exists for update of Relying party on adapter ");
        $span = $this->startSpan("Exists for update of Relying party on adapter");
        try {
            return $this->conn->existsForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function countForUpdate(?RelyingPartyFilter $filter = null): int
    {
        $this->logDebug("Count for update of Relying party on adapter ");
        $span = $this->startSpan("Count for update of Relying party on adapter");
        try {
            return $this->conn->countForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function create(RelyingParty $entity, ?Closure $verify = null): RelyingParty
    {
        $this->logDebug("Count for Relying party on adapter ");
        $span = $this->startSpan("Count for Relying party on adapter");
        try {
            $created = $this->conn->create($entity, $verify);
            $this->dispatch($entity);
            $this->changelog->recordChange('relying-party', $entity->uid(), $entity->asPublicJson(), []);
            return $created;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function update(RelyingPartyRef $ref, RelyingParty $entity): RelyingParty
    {
        $this->logDebug("Count for Relying party on adapter ");
        $span = $this->startSpan("Count for Relying party on adapter");
        try {
            $original = ($ref instanceof RelyingParty) ? $ref : $this->conn->retrieve(new RelyingPartyFilter(uids: [ $ref->uid() ]));
            \assert($original !== null);
            $updated = $this->conn->update($entity);
            $this->dispatch($entity);
            $this->changelog->recordChange('relying-party', $entity->uid(), $entity->asPublicJson(), $original->asPublicJson());
            return $updated;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function delete(RelyingParty $entity): bool
    {
        $this->logDebug("Count for Relying party on adapter ");
        $span = $this->startSpan("Count for Relying party on adapter");
        try {
            $result = $this->conn->delete($entity);
            $this->dispatch($entity);
            $this->changelog->recordDeletion('relying-party', $entity->uid(), $entity->asPublicJson());
            return $result;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneForUpdateByUid(string $uid): ?RelyingParty
    {
        $this->logDebug("Find on by uid for Relying party on adapter");
        $span = $this->startSpan("Find on by uid for Relying party on adapter");
        try {
            return $this->conn->retrieveForUpdate(new RelyingPartyFilter(uids: [$uid]));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneForUpdateByCode(string $code): ?RelyingParty
    {
        $this->logDebug("Find on by code for Relying party on adapter");
        $span = $this->startSpan("Find on by code for Relying party on adapter");
        try {
            return $this->conn->retrieveForUpdate(new RelyingPartyFilter(code: $code));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneForUpdateByApiKey(string $apiKey): ?RelyingParty
    {
        $this->logDebug("Find on by api key for Relying party on adapter");
        $span = $this->startSpan("Find on by api key for Relying party on adapter");
        try {
            return $this->conn->retrieveForUpdate(new RelyingPartyFilter(apiKey: $apiKey));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function dispatch(RelyingParty $entity): void
    {
        $this->logDebug("Count for Relying party on adapter ");
        $span = $this->startSpan("Count for Relying party on adapter");
        try {
            foreach ($entity->getTheEvents() as $event) {
                $this->dispatcher->dispatch($event);
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
